/// <summary>
/// PricingAttribute of table <c>CustTable</c> field AccountNum.
/// </summary>
[GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Customer, GUPPricingAttributeSourceLevel::Header)]
[GUPPricingAttributeFieldsDiscovery(fieldStr(CustTable, AccountNum))]
internal class GUPPricingAttributeCustTableAccountNum extends GUPPricingAttributeCustTable implements GUPIPricingAttribute
{

}

Method.Source:
public str getName()
{
    return fieldPName(CustTable, AccountNum);
}

public Set getAllowedValuesWithDescription()
{
    var ret = new Set(Types::AnyType);

    CustTable custTable;

    while select AccountNum, Party from custTable            
    {
        GUPPricingAttributeAllowedValuesObject valueObject =
            new GUPPricingAttributeAllowedValuesObject(custTable.AccountNum, custTable.name());
        ret.add(valueObject);
    }
    return ret;
}
